package com.heluo.museum.store;
import com.heluo.museum.common.api.ApiResponse;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/products") public class ProductController {private final JdbcTemplate jdbc;ProductController(JdbcTemplate jdbc){this.jdbc=jdbc;}@GetMapping public ApiResponse<List<Card>> list(){return ApiResponse.ok(jdbc.query("select slug,name,summary,price,stock_quantity,locked_stock,cover_image_url from products where status='PUBLISHED' and deleted_at is null order by published_at desc,id desc",(r,n)->new Card(r.getString(1),r.getString(2),r.getString(3),r.getBigDecimal(4).toPlainString(),Math.max(0,r.getInt(5)-r.getInt(6)),r.getString(7))),"products");}@GetMapping("/{slug}") public ApiResponse<java.util.Map<String,Object>> detail(@PathVariable String slug){var r=jdbc.queryForMap("select slug,name,summary,description,price,stock_quantity,locked_stock,cover_image_url from products where slug=? and status='PUBLISHED' and deleted_at is null",slug);return ApiResponse.ok(java.util.Map.of("slug",r.get("slug"),"name",r.get("name"),"summary",r.get("summary")==null?"":r.get("summary"),"description",r.get("description")==null?"":r.get("description"),"price",r.get("price").toString(),"availableStock",Math.max(0,((Number)r.get("stock_quantity")).intValue()-((Number)r.get("locked_stock")).intValue()),"coverImageUrl",r.get("cover_image_url")==null?"":r.get("cover_image_url")),"product");}public record Card(String slug,String name,String summary,String price,int availableStock,String coverImageUrl){}}

